import React, { useState, useEffect } from "react";
import { auth, db } from "../../firebase"; // Make sure to adjust your Firebase import
import { doc, getDoc, setDoc, updateDoc, collection, addDoc } from "firebase/firestore"; // Firebase Firestore methods
import UserHeader from "components/Headers/UserHeader.js"; // Ensure correct import path for the header component

const Profile = () => {
  const [userData, setUserData] = useState({
    username: "",
    email: "",
    firstName: "",
    lastName: "",
    address: "",
    city: "",
    country: "",
    postalCode: "",
    aboutMe: "",
  });

  const [carbonFootprint, setCarbonFootprint] = useState({
    carUsageKm: "",
    vehicleType: "",
    fuelType: "",
    publicTransportTrips: "",
    publicTransportMode: "",
    flightsPerYear: "",
    electricityUsage: "",
    heatingMethod: "",
    homeSize: "",
    energyEfficientAppliances: false,
    dietType: "",
    meatFrequency: "",
    recyclingHabit: false,
    wasteGeneration: "",
    renewableEnergyUse: false,
    ecoFriendlyProducts: false,
    sustainableShopping: false,
    carbonOffsetProgram: "",
    carbonOffsetDetails: "",
    additionalNotes: "",
  });

  useEffect(() => {
    const fetchUserData = async () => {
      const user = auth.currentUser;
      if (user) {
        const userRef = doc(db, "users", `${user.uid}-userinfo`); // Correctly using template literal for user UID
        const docSnap = await getDoc(userRef);
        if (docSnap.exists()) {
          setUserData(docSnap.data()); // Fill the form with existing user data if it exists
        }
      }
    };

    fetchUserData();
  }, []);

  const handleProfileChange = (e) => {
    const { id, value } = e.target;
    setUserData({ ...userData, [id]: value });
  };

  const handleCarbonFootprintChange = (e) => {
    const { id, value, type, checked } = e.target;
    setCarbonFootprint({
      ...carbonFootprint,
      [id]: type === "checkbox" ? checked : value,
    });
  };

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    const user = auth.currentUser;
    if (user) {
      const userRef = doc(db, "users", `${user.uid}-userinfo`);

      try {
        // Check if the document exists for user profile
        const docSnap = await getDoc(userRef);
        if (docSnap.exists()) {
          // Update profile data if document exists
          await updateDoc(userRef, userData);
          alert("Profile updated successfully!");
        } else {
          // Create new profile document if it doesn't exist
          await setDoc(userRef, userData);
          alert("Profile created successfully!");
        }
      } catch (error) {
        console.error("Error updating profile: ", error);
        alert("Failed to update profile.");
      }
    }
  };

  const handleCarbonFootprintSubmit = async (e) => {
    e.preventDefault();
    const user = auth.currentUser;
    if (user) {
      const userFootprintRef = collection(db, "users", `${user.uid}-userinfo`, "FootPrint");

      try {
        // Add a new footprint document under the 'FootPrint' subcollection
        await addDoc(userFootprintRef, carbonFootprint);
        alert("Carbon footprint data submitted successfully!");
      } catch (error) {
        console.error("Error submitting carbon footprint: ", error);
        alert("Failed to submit carbon footprint.");
      }
    }
  };

  return (
    <>
      <UserHeader /> {/* Add the UserHeader component here */}

      {/* Profile Form */}
      <div className="container mt-5">
        <h2>Profile Information</h2>
        <form onSubmit={handleProfileSubmit}>
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <input
              id="username"
              type="text"
              className="form-control"
              value={userData.username}
              onChange={handleProfileChange}
            />
          </div>
          {/* Add other profile fields here as per the state defined */}
          <div className="form-group">
            <label htmlFor="email">Email</label>
            <input
              id="email"
              type="email"
              className="form-control"
              value={userData.email}
              onChange={handleProfileChange}
            />
          </div>
          {/* Add other profile fields */}
          <button type="submit" className="btn btn-primary">Save Profile</button>
        </form>
      </div>

      {/* Carbon Footprint Form */}
      <div className="container mt-5">
        <h2>Carbon Footprint Information</h2>
        <form onSubmit={handleCarbonFootprintSubmit}>
          <div className="form-group">
            <label htmlFor="carUsageKm">Number of kilometers driven daily</label>
            <input
              id="carUsageKm"
              type="number"
              className="form-control"
              value={carbonFootprint.carUsageKm}
              onChange={handleCarbonFootprintChange}
            />
          </div>
          <div className="form-group">
            <label htmlFor="vehicleType">Type of vehicle</label>
            <input
              id="vehicleType"
              type="text"
              className="form-control"
              value={carbonFootprint.vehicleType}
              onChange={handleCarbonFootprintChange}
            />
          </div>
          {/* Add other carbon footprint fields */}
          <button type="submit" className="btn btn-primary">Submit Footprint</button>
        </form>
      </div>
    </>
  );
};

export default Profile;
